mapper.update:
UPDATE purchase_demand_allocation
SET allocated_quantity = #{allocatedQuantity},
    version            = version + 1,
    updated_at         = CURRENT_TIMESTAMP,
    updated_by         = #{operator}
WHERE id = #{id}
  AND version = #{version}
  AND deleted = FALSE

UPDATE purchase_demand_allocation
SET deleted    = TRUE,
    version    = version + 1,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = #{id}
  AND version = #{version}
  AND deleted = FALSE
